S=/private/tmp/claude-501/-Users-tprahlad-dev-spike-sorting/3c947ebc-0a9e-4010-b985-45f9ab9aea41/scratchpad
cat > $S/check_tests.py <<'EOF'
import sys, numpy as np, pytest
sys.path.insert(0, "/Users/tprahlad/dev/spike-sorting")
from spikesort import hh
def ionic_currents(y):
    v, m, h, n = y
    return hh.G_NA*m**3*h*(v-hh.E_NA), hh.G_K*n**4*(v-hh.E_K), hh.G_L*(v-hh.E_L)
def hh_rhs(t, y, i_ext):
    v, m, h, n = y
    a_m,b_m,a_h,b_h,a_n,b_n = hh.rates(v)
    return np.array([(i_ext(t)-sum(ionic_currents(y)))/hh.C_M, a_m*(1-m)-b_m*m, a_h*(1-h)-b_h*h, a_n*(1-n)-b_n*n])
def rk4_step(f, t, y, dt):
    k1=f(t,y); k2=f(t+dt/2,y+dt/2*k1); k3=f(t+dt/2,y+dt/2*k2); k4=f(t+dt,y+dt*k3)
    return y+dt/6*(k1+2*k2+2*k3+k4)
hh.ionic_currents, hh.hh_rhs, hh.rk4_step = ionic_currents, hh_rhs, rk4_step
sys.exit(pytest.main(["-q", "-p", "no:cacheprovider", "/Users/tprahlad/dev/spike-sorting/tests"]))
EOF
cd /Users/tprahlad/dev/spike-sorting && .venv/bin/python $S/check_tests.py 2>&1 | tail -4

